import json
from decimal import Decimal, ROUND_HALF_UP


def load(path):
    with open(path, encoding="utf-8") as f:
        return json.load(f, parse_float=Decimal, parse_int=Decimal)


def main():
    orders = load("дані/замовлення.json")
    codes = load("дані/коди.json")
    codes = {str(k): v for k, v in codes.items()}

    totals = {}
    cent = Decimal("0.01")
    for order in orders:
        code = order.get("код")
        discount = Decimal(0)
        if code is not None and str(code) in codes:
            discount = Decimal(codes[str(code)])
        for item in order.get("позиції", []):
            price = Decimal(item["ціна"])
            qty = Decimal(item["кількість"])
            revenue = (price * qty * (Decimal(100) - discount) / Decimal(100)).quantize(
                cent, rounding=ROUND_HALF_UP
            )
            cat = item["категорія"]
            totals[cat] = totals.get(cat, Decimal(0)) + revenue

